/*
 * The Drylake mark: the cracked lake-bed tile (logo option 4, Wilson's choice, adopted by Ben
 * 2026-10-07, drylake-ops D27). Five plates; the ochre one is "the part we work on", and the
 * cracks read as connected systems. Identical geometry to public/brand/drylake-mark-tile.svg
 * (generated by scripts/brand/generate-tile.py, test-pinned).
 *
 * Cracks are a stroke in the surface colour, so pass the colour the tile sits on.
 * Decorative here: the accessible name comes from the link around it.
 */
export const TILE_PLATES = [
  "M8 8 H44 L40 38 L8 46 Z",
  "M50 8 H92 V30 L60 40 L46 36 Z",
  "M8 52 L42 44 L52 62 L40 92 H8 Z",
  "M48 42 L62 46 L92 36 V62 L70 70 L56 62 Z",
  "M58 68 L92 68 V92 H46 Z",
] as const;

export const TILE_OCHRE = "#C2703D";
export const TILE_OCHRE_PLATE = 3;

/* The y of the wordmark, still part of the logo (the closing CTA traces it). */
export const MARK_Y_PATH =
  "M141.63,-46.04 L158.84,-1.42 M176.05,-46.04 L156.71,4.10 C153.61,12.13 146.51,20.49 138.00,20.49 C132.29,20.49 126.54,7.44 122.97,6.27";

/* Plates only, for use inside another SVG (draw at 0..100; caller transforms). */
export function TilePlates({
  surface = "#0f1013",
  ink = "#ECEAE4",
  small = false,
}: {
  surface?: string;
  ink?: string;
  small?: boolean;
}) {
  return (
    <>
      {TILE_PLATES.map((d, index) => (
        <path
          key={d}
          d={d}
          fill={index === TILE_OCHRE_PLATE ? TILE_OCHRE : ink}
          stroke={surface}
          strokeWidth={small ? 8 : 4.5}
          strokeLinejoin="round"
        />
      ))}
    </>
  );
}

export default function DrylakeMark({
  className,
  surface = "#0f1013",
  tone = "dark",
}: {
  className?: string;
  surface?: string;
  tone?: "dark" | "light";
}) {
  const ink = tone === "dark" ? "#ECEAE4" : "#17191E";

  return (
    <svg viewBox="4 4 92 92" aria-hidden="true" focusable="false" className={className}>
      <defs>
        <clipPath id={`dl-tile-${tone}`}>
          <rect x="4" y="4" width="92" height="92" rx="18" />
        </clipPath>
      </defs>
      <g clipPath={`url(#dl-tile-${tone})`}>
        <rect x="0" y="0" width="100" height="100" fill={surface} />
        <TilePlates surface={surface} ink={ink} />
      </g>
    </svg>
  );
}
